function validate([root]) {
  if (root.length === 0 || root[0] === null) return 'The tree needs at least 1 node.';
  const values = root.filter(v => v !== null);
  if (values.length > 100000) return 'The tree has at most 10^5 nodes.';
  if (values.some(v => v < 1 || v > 1000000000)) return 'Every node value is between 1 and 10^9.';
  return null;
}

