function minimumLevel(root) {
  // Depth-first with a stack: add each value into the total for its depth, then take the first smallest total.
  const sums = [];
  const stack = [[root, 0]];
  while (stack.length) {
    const [node, depth] = stack.pop();
    if (!node) continue;
    sums[depth] = (sums[depth] || 0) + node.val;
    stack.push([node.left, depth + 1], [node.right, depth + 1]);
  }
  let best = 0;
  for (let d = 1; d < sums.length; d++) if (sums[d] < sums[best]) best = d;
  return best + 1;
}

