function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 900 + Math.floor(rand() * 100) : 1 + Math.floor(rand() * 12);
  const mode = rand();
  const constant = 1 + Math.floor(rand() * 1000000000);
  // Values are all equal, tiny (many ties), anywhere in range, or scaled per level so different levels win.
  const scales = [];
  const value = (depth) => {
    if (mode < 0.15) return constant;
    if (mode < 0.4) return 1 + Math.floor(rand() * 3);
    if (mode < 0.65) return 1 + Math.floor(rand() * 1000000000);
    if (scales[depth] === undefined) scales[depth] = rand() < 0.5 ? 1 : 100000000;
    return (1 + Math.floor(rand() * 9)) * scales[depth];
  };
  // Some trees start with a long downward chain, which makes many levels.
  const chain = large ? (rand() < 0.4 ? 100 + Math.floor(rand() * 300) : 1) : (rand() < 0.25 ? n : 1);
  const nodes = [{ val: value(0), depth: 0, left: null, right: null }];
  for (let i = 1; i < chain; i++) {
    nodes[i - 1][rand() < 0.5 ? 'left' : 'right'] = i;
    nodes.push({ val: value(i), depth: i, left: null, right: null });
  }
  const slots = [[chain - 1, 'left'], [chain - 1, 'right']];
  for (let i = chain; i < n; i++) {
    const k = Math.floor(rand() * slots.length);
    const [parent, side] = slots[k];
    slots[k] = slots[slots.length - 1];
    slots.pop();
    nodes[parent][side] = i;
    const depth = nodes[parent].depth + 1;
    nodes.push({ val: value(depth), depth, left: null, right: null });
    slots.push([i, 'left'], [i, 'right']);
  }
  // Level-order serialisation with null for missing children, trailing nulls removed.
  const out = [];
  const queue = [0];
  for (let q = 0; q < queue.length; q++) {
    if (queue[q] === null) { out.push(null); continue; }
    const node = nodes[queue[q]];
    out.push(node.val);
    queue.push(node.left, node.right);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return [out];
}
